import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const scope={window:{}};vm.runInNewContext(fs.readFileSync('js/nagweb-story-model.js','utf8'),scope);const m=scope.window.NAGWEB_STREAM_MODEL,cfg=m.config({kind:'sphere-wall'}),plain=x=>JSON.parse(JSON.stringify(x)),pose=(p,c={},n=8,w=1280,h=720)=>m.layout(w,h,{...cfg,...c},p,n,1.6),near=(a,b,t=1e-5)=>assert.ok(Math.abs(a-b)<t,`${a} != ${b}`);
assert.equal(cfg.kind,'sphere-wall');assert.equal(cfg.cardRatio,'16:9');assert.equal(cfg.motion,'continuous');assert.equal(cfg.direction,'left');assert.equal(cfg.focusStyle,'overlap');for(const [key,s] of Object.entries(m.sphereSpecs)){assert.equal(cfg[key],s[0]);assert.equal(m.config({kind:'sphere-wall',[key]:-999})[key],s[1]);assert.equal(m.config({kind:'sphere-wall',[key]:999})[key],s[2]);}assert.equal(m.config({kind:'sphere-wall',motion:'invalid',direction:'invalid',focusStyle:'invalid'}).motion,'continuous');
for(const [n,expected] of [[0,8],[1,4],[4,4],[30,30],[99,30]])assert.equal(pose(0,{},n).length,expected);
for(const motion of ['continuous','waypoints','waypoints-move'])for(const direction of ['left','right','alternate']){const c={motion,direction};assert.deepEqual(plain(pose(0,c)),plain(pose(1,c)));for(const p of [0,.0317,.16/5,.5/5,.84/5,.317,.999]){const cards=pose(p,c);assert.ok(cards.some(card=>card.visible),'The wall must visibly render');for(const card of cards){for(const k of ['left','top','width','height','textureWidth','textureHeight','corner','zoom','depth'])assert.ok(Number.isFinite(card[k]),k);assert.ok(card.width<=1280+1e-5&&card.height<=720+1e-5);for(const t of card.instances){assert.ok(t.alpha>0&&t.alpha<=1&&t.shade>=0&&t.shade<=1);assert.ok(t.mesh.columns<=64&&t.mesh.rows<=48);assert.equal(!!t.homography,motion!=='continuous');for(const v of t.mesh.vertices.filter(Boolean))assert.ok(Number.isFinite(v.x)&&Number.isFinite(v.y));const center=m.meshPoint(t.mesh,.5,.5);if(center){const uv=m.meshUV(t.mesh,center.x,center.y);assert.ok(uv);near(uv.u,.5,.001);near(uv.v,.5,.001);}assert.equal(m.meshUV(t.mesh,-1e8,-1e8),null);}}}}
const base=pose(0),zero=base[0].instances.find(t=>t.row===0&&t.column===0);assert.ok(zero);near(zero.center.x,640);near(zero.center.y,360);near(base[0].textureWidth,(1280-2*7.2*13-4*7.2*5)/5);near(base[0].textureHeight,base[0].textureWidth/(16/9));assert.ok(zero.mesh.columns>=8&&zero.mesh.rows>=6);
const left=pose(.01),right=pose(.01,{direction:'right'});assert.ok(left.flatMap(x=>x.instances).find(t=>t.row===0&&t.column===0).center.x<640);assert.ok(right.flatMap(x=>x.instances).find(t=>t.row===0&&t.column===0).center.x>640);const alternate=pose(.01,{direction:'alternate'}).flatMap(x=>x.instances);assert.ok(alternate.find(t=>t.row===1&&t.column===0).center.x>640);assert.ok(alternate.find(t=>t.row===-1&&t.column===0).center.x>640);
for(const motion of ['waypoints','waypoints-move']){const hold=pose(0,{motion}),center=hold.flatMap(card=>card.instances.map(t=>({card,t}))).find(({t})=>Math.hypot(t.center.x-640,t.center.y-360)<1e-6);assert.ok(center);near(center.card.zoom,motion==='waypoints'?2.8:1);near(pose(.5/5,{motion})[0].zoom,1);assert.deepEqual(plain(hold),plain(pose(.1/5,{motion})));const spotlight=pose(0,{motion,focusStyle:'spotlight'});assert.ok(spotlight.flatMap(x=>x.instances).reduce((n,t)=>n+t.alpha,0)<hold.flatMap(x=>x.instances).length);for(const t of spotlight.flatMap(x=>x.instances))assert.equal(t.shade,1);}
const faded=pose(0,{edgeFade:100});assert.ok(faded.flatMap(x=>x.instances).some(t=>t.shade<.99));for(const t of faded.flatMap(x=>x.instances))assert.equal(t.alpha,1);
for(const [w,h] of [[1280,720],[390,844],[360,360]])for(const curvature of [-150,0,150])for(const motion of ['continuous','waypoints'])for(const cardRatio of ['auto','9:16','16:9']){const cards=pose(.317,{frameRatio:'auto',curvature,motion,cardRatio,tilt:45,zoom:50,focusZoom:4,cornerRadius:12},30,w,h);assert.ok(cards.some(x=>x.visible));for(const t of cards.flatMap(x=>x.instances)){assert.ok(t.width<=w+1e-5&&t.height<=h+1e-5);assert.ok(Number.isFinite(t.depth));}}
for(const c of [{zoom:10,gap:20,padding:20},{zoom:50,gap:.5,curvature:-150,focusZoom:4,motion:'waypoints'},{zoom:50,gap:.5,curvature:150}]){const cards=pose(.317,{frameRatio:'auto',...c},4,390,844);assert.ok(cards.some(x=>x.visible));assert.ok(cards.every(x=>x.textureWidth>=2&&Number.isFinite(x.width)));}
const scroll={motion:'waypoints',start:20,end:80,turns:3};assert.deepEqual(plain(m.layout(390,844,{...cfg,...scroll},.1,8,1.6,true)),plain(m.layout(390,844,{...cfg,...scroll},.9,8,1.6,true)));
console.log('Sphere Wall: HAR curved two-axis projection, directions/alternate parity, deterministic waypoints/zoom/holds/spotlight, closed loops, shading versus alpha, rounded mesh picking, finite clipped extreme/mobile geometry and scroll OK');
